function makeEnemy(){
 const group=new THREE.Group();
 const hull=mat(0x8e9ba8,0x343b53,.45,.82,.24);
 const underside=mat(0x34384e,0x74194b,.7,.72,.3);
 const glass=mat(0x56dbe0,0x25dcea,1.8,.48,.14);
